class Widget {};

// Factory function clearly transfers ownership to the caller.
std::unique_ptr<Widget> createWidget() {
    return std::make_unique<Widget>();
}

void process() {
    // pW1 owns the new Widget.
    std::unique_ptr<Widget> pW1 = createWidget();

    // Ownership is transferred from pW1 to pW2. pW1 is now null.
    std::unique_ptr<Widget> pW2 = std::move(pW1);

    if (pW2) { // Can check if the pointer is non-null.
        // ... use pW2
    }

    // auto pW3 = pW2; // COMPILE ERROR: std::unique_ptr is not copyable.

    // The Widget is automatically deleted when pW2 goes out of scope.
}

// Managing a dynamically allocated array.
std::unique_ptr<int[]> pArray = std::make_unique<int[]>(10);
pArray[0] = 42; // Array access is supported.
